TLM.f("Tempora/Pasc7-1",{"officium":"Die II infra octavam Pentecostes","rule":["Gloria","Sequentia","Credo","Prefatio=Spiritu=hodierna die;"],"ruleInherited":["Gloria","Sequentia","Credo","Prefatio=Spiritu=hodierna die;"],"fallback":"Tempora/Pasc7-0","sections":{"Introitus":[{"k":"ref","la":"Ps 80:17"},{"k":"text","la":"Cibávit eos ex ádipe fruménti, allelúja: et de petra, melle saturávit eos, allelúja, allelúja."},{"k":"ref","la":"Ps 80:2"},{"k":"text","la":"Exsultáte Deo, adjutóri nostro: jubiláte Deo Jacob."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Cibávit eos ex ádipe fruménti, allelúja: et de petra, melle saturávit eos, allelúja, allelúja."}],"Oratio":[{"k":"text","la":"Deus, qui Apóstolis tuis Sanctum dedísti Spíritum: concéde plebi tuæ piæ petitiónis efféctum; ut, quibus dedísti fidem, largiáris et pacem."},{"k":"macro","name":"Per Dominum eiusdem"}],"Lectio":[{"k":"text","la":"Léctio Actuum Apostolórum"},{"k":"ref","la":"Acts 10:34; 10:42-48"},{"k":"text","la":"In diébus illis: Apériens Petrus os suum, dixit: Viri fratres, nobis præcépit Dóminus prædicáre pópulo: et testificári, quia ipse est, qui constitútus est a Deo judex vivórum et mortuórum. Huic omnes Prophétæ testimónium pérhibent, remissiónem peccatórum accípere per nomen ejus omnes, qui credunt in eum. Adhuc loquénte Petro verba hæc, cecidit Spíritus Sanctus super omnes, qui audiébant verbum. Et obstupuérunt ex circumcisióne fidéles, qui vénerant cum Petro: quia et in natiónes grátia Spíritus Sancti effúsa est. Audiébant enim illos loquéntes linguis et magnificántes Deum. Tunc respóndit Petrus: Numquid aquam quis prohibére potest, ut non baptizéntur hi, qui Spíritum Sanctum accepérunt sicut et nos? Et jussit eos baptizári in nómine Dómini Jesu Christi."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Acts 2:4"},{"k":"text","la":"Loquebántur váriis linguis Apóstoli magnália Dei. Allelúja. (Hic genuflectitur)"},{"k":"text","la":"Veni, Sancte Spiritus, reple tuorum corda fidélium: et tui amóris in eis ignem accénde.","mark":"V"}],"Sequentia":[{"k":"text","la":"Veni, Sancte Spíritus,"},{"k":"text","la":"et emítte cǽlitus"},{"k":"text","la":"lucis tuæ rádium."},{"k":"sep"},{"k":"text","la":"Veni, pater páuperum;"},{"k":"text","la":"veni, dator múnerum;"},{"k":"text","la":"veni, lumen córdium."},{"k":"sep"},{"k":"text","la":"Consolátor óptime,"},{"k":"text","la":"dulcis hospes ánimæ,"},{"k":"text","la":"dulce refrigérium."},{"k":"sep"},{"k":"text","la":"In labóre réquies,"},{"k":"text","la":"in æstu tempéries,"},{"k":"text","la":"in fletu solácium."},{"k":"sep"},{"k":"text","la":"O lux beatíssima,"},{"k":"text","la":"reple cordis íntima"},{"k":"text","la":"tuórum fidélium."},{"k":"sep"},{"k":"text","la":"Sine tuo númine"},{"k":"text","la":"nihil est in hómine,"},{"k":"text","la":"nihil est innóxium."},{"k":"sep"},{"k":"text","la":"Lava quod est sórdidum,"},{"k":"text","la":"riga quod est áridum,"},{"k":"text","la":"sana quod est sáucium."},{"k":"sep"},{"k":"text","la":"Flecte quod est rígidum,"},{"k":"text","la":"fove quod est frígidum,"},{"k":"text","la":"rege quod est dévium."},{"k":"sep"},{"k":"text","la":"Da tuis fidélibus,"},{"k":"text","la":"in te confidéntibus,"},{"k":"text","la":"sacrum septenárium."},{"k":"sep"},{"k":"text","la":"Da virtútis méritum,"},{"k":"text","la":"da salútis éxitum,"},{"k":"text","la":"da perénne gáudium."},{"k":"text","la":"Amen. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joannes 3:16-21"},{"k":"text","la":"In illo témpore: Dixit Jesus Nicodémo: Sic Deus diléxit mundum, ut Fílium suum unigénitum daret: ut omnis, qui credit in eum, non péreat, sed hábeat vitam ætérnam. Non enim misit Deus Fílium suum in mundum, ut júdicet mundum, sed ut salvétur mundus per ipsum. Qui credit in eum, non judicátur; qui autem non credit, jam judicátus est: quia non credit in nómine unigéniti Fílii Dei. Hoc est autem judícium: quia lux venit in mundum, et dilexérunt hómines magis ténebras quam lucem: erant enim eórum mala ópera. Omnis enim, qui male agit, odit lucem, et non venit ad lucem, ut non arguántur ópera ejus: qui autem facit veritátem, venit ad lucem, ut manifesténtur ópera ejus, quia in Deo sunt facta."}],"Offertorium":[{"k":"ref","la":"Ps 17:14 et 16"},{"k":"text","la":"Intónuit de cœlo Dóminus, et Altíssimus dedit vocem suam: et apparuérunt fontes aquárum, allelúja."}],"Secreta":[{"k":"text","la":"Propítius, Dómine, quǽsumus, hæc dona sanctífica: et, hóstiæ spiritális oblatióne suscépta, nosmetípsos tibi pérfice munus ætérnum."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Joannes 14:26"},{"k":"text","la":"Spíritus Sanctus docébit vos, allelúja: quæcúmque díxero vobis, allelúja, allelúja."}],"Postcommunio":[{"k":"text","la":"Adésto, quǽsumus, Dómine, pópulo tuo: et, quem mystériis cœléstibus imbuísti, ab hóstium furóre defénde."},{"k":"macro","name":"Per Dominum"}]},"hr":{"619fc3578b85ae07":{"t":"Ps 80, 17, Ps 80, 2\n(Ps 80, 17) Nahranio ih je najboljom pšenicom, <i>aleluja</i>.\nI nasitio ih je medom iz pećine, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 80, 2) Kličite Bogu, našem pomagaču! Veličajte Boga Jakovljeva.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 80, 17) Nahranio ih je najboljom pšenicom, <i>aleluja</i>.\nI nasitio ih je medom iz pećine, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Ps. 80, 11). Nahranio ih je pšeničnom srži, aleluja, i medom dz stijene nasitio ih je, aleluja, aleluja. (Ps. 80, 2) Radujte se Bogu, pomoćniku našemu, kličite Bogu Jakovljevu. Slava Ocu . . . Nahranio ih je . . , <i>aleluja</i>, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 344–345 (snimka 173) (OCR)"},"95fa097a565d8cdc":{"t":"<i>Pomolimo se</i>.\nBože, koji si svojim apostolima dao Duha Svetoga, dopusti puku svomu da postigne što pobožno moli te daruj mir onima kojima si dao da vjeruju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu istog Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si svojim apostolima dao Duha Svetoga, dopusti puku svomu, da dostigne, što pobožno moli, te daruj mir onima, kojima si dao da vjeruju, po G. n, . . . u jedinstvu istoga Duhei . . .","knRef":"Kniewald 1942, str. 344–345 (snimka 173) (OCR)"},"fc45b42329654bac":{"t":"Dj 10, 34 i 42-48\nČitanje Djela apostolskih. U one dane progovori Petar: Ljudi, braćo! Gospodin nam je zapovjedio da narodu propovijedamo i svjedočimo da je on postavljen od Boga za suca živima i mrtvima. Svi proroci svjedoče za njega, da svi koji vjeruju u njega dobivaju po njemu oprost od grijeha. Dok je još Petar govorio ove riječi, siđe Duh Sveti na sve koji su slušali govor. I vjernici od obrezanika koji su došli s Petrom začudiše se što se i na neznabošce izlila milost Duha Svetoga, jer su ih čuli gdje govore jezicima i veličaju Boga. Tada Petar reče: Može li tko uskratiti vodu da se ne krste ovi koji su primili Duha Svetoga kao i mi? I zapovjedi da budu kršteni u ime Gospodina Isusa Krista.","kn":"Čitanje Djela apostolskih (10, 42-48). U one dane progovori Petar: Ljudi, braćo! Gospodin nam je zapovjedio, da naro'du propovijedamo i svjedočimo, da je on postavljen od Boga za suca živima i mrtvima. Svi proroci svjedoče za njega, da svi, koji vjeruju u njega, dobivaju po njemu oprost od grijeha. Dok je još Petar govorio ove riječi, siđe Duh Sveti na sve, koji su slušali govor. I vjernici od obrezanlka, koji su došli s Petrom, začudiše se, što se i na neznabošce izlila milost Duha Svetoga, jer EU ih čuli, gdje govore Jezicima i veličaju Boga. Tada Petar reče: Može li tko uskratiti vodu, da se ne krste ovi, koji su primili Duha Svetoga kao i mi? I zapovjedi, da budu kršteni u ime Gospodina Isusa Krista.","knRef":"Kniewald 1942, str. 344–345 (snimka 173) (OCR)"},"6bcff0acc37fbed5":{"t":"Act 2, 4\n<i>Aleluja</i>, <i>aleluja</i>.\nStadoše apostoli govoriti tuđim jezicima o divnim djelima Božjim. <i>Aleluja</i>.\n[Ovdje se poklekne] Dođi, Duše Sveti, napuni srca svojih vjernika i zapali u njima oganj svoje ljubavi.","kn":"Aleluja, aleluja (Dj. aip. 2, 4). Stadoše apostoli govoriti tuđim jezicima o divnim djelima Božjim, aleluja. Ovdje se poklekne. Dođi, Duše Sveti, napuni srca svojih vjernih i zapali u njima oganj svoje ljubavi.","knRef":"Kniewald 1942, str. 346–347 (snimka 174) (OCR)"},"8986d237bd5894a0":{"t":"Dođi, duše presveti, /Sa neba nas posjeti /Zrakom svoje milosti. <i>\n</i>\nDođi, Oče ubogih,/Djelitelju dara svih,/Dođi, srca svjetlosti. <i>\n</i>\nTješitelju tako blag, /Ti nebeski Goste drag, /Pun miline hlade tih. <i>\n</i>\nUmornima odmore,/U vrućini lahore,/Razgovore žalosnih. <i>\n</i>\nSjaju svjetla blaženog,/Sjaj u srcu puka svog,/Napuni nam dušu svu. <i>\n</i>\nBez božanstva tvojega /Svi smo mi bez ičega,/Tonemo u crnom zlu. <i>\n</i>\nNečiste nas umivaj,/Suha srca zalivaj, /Vidaj rane ranjenim. <i>\n</i>\nMekšaj ćudi kamene,/ Zagrij grudi ledene,/Ne daj nama putem zlim. <i>\n</i>\nSvim što vjeru imaju,/Što se u te ufaju, /Sedam svojih dara daj. <i>\n</i>\nDaj nam krepost zaslužnu/I smrt lijepu, blaženu,/Daj vjekovit svima raj. <i>\n</i>\n<i>amen</i>, <i>aleluja</i>."},"a221de7bee30c38d":{"t":"Iv 3, 16-21\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme reče Isus Nikodemu: Bog je tako ljubio svijet da je dao svoga Jedinorođenog Sina da ne pogine ni jedan koji vjeruje u njega, nego da ima život vječni. Bog nije poslao svoga Sina na svijet da sudi svijetu, nego da se svijet spasi po njemu. Tko u njega vjeruje, ne sudi mu se, a tko ne vjeruje, već je osuđen jer ne vjeruje u Božjega Jedinorođenog Sina. A to je osuda što je svjetlost došla na svijet, ali ljudi su ljubili više tamu nego svjetlost jer su bila opaka njihova djela. Svaki koji čini zlo mrzi svjetlost i ne ide na svjetlost da se ne pokažu njegova djela. A onaj koji živi po istini, dolazi na svjetlost da se očituju njegova djela jer su učinjena u Bogu.","kn":"t Slijedi sveto evanđelje po Ivanu (3, 16-21). U ono vrijeme reče Isus Nikodemu: Bog je takO' ljubio svijet, da je dao svoga Jedinorođenca^ da ne pogine nijedan, koji vjeruje u njega, nego da ima život vječni. Jer Bog nije poslao svoga Sina na svijet, da sudi svijetu, nego da se svijet spasi po njemu. Tko u njega vjeruje, ne sudi mu se, a tko ne vjeruje, već je osuđen, jer ne vjeruje u Božjega Jedinorođenca. A to je osuda, što je svjetlost došla na svijet, ali ljudi su ljubili više tamu nego svjetlost, jer su bila opaka njihova djela. Svaki, koji čini zlo, mrzi svjetlost i ne ide na svjetlost, da se ne pokažu njegova djela. A onaj, koji živi po istini, dolazi na svjetlost, da se očituju njegova djela, jer su učinjena u Bogu.","knRef":"Kniewald 1942, str. 346–347 (snimka 174) (OCR)"},"7d383d3ca7290b3e":{"t":"Ps 17, 14 i 16\nS neba je zagrmio Gospodin. Višnji je dao glas svoj i pojaviše se izvori voda, <i>aleluja</i>.","kn":"(Ps: 17, 14, 16). S neba je zagrmio Gospodin. Višnji je dao glas svoj. i pojaviše se izvori voda, aleluja.","knRef":"Kniewald 1942, str. 306–307 (snimka 154) (OCR)"},"3c0995f7ffa2072e":{"t":"Molimo, Gospodine, posveti milostivo ove darove i primivši prikazanje duhovne žrtve učini i nas same sebi vječnim darom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, posveti milostivo ove darove i primivši prikazanje duhovne žrtve učini i nas same sebi vječnim darom, po G. n.","knRef":"Kniewald 1942, str. 346–347 (snimka 174) (OCR)"},"e36be14714c3ff04":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. On uziđe nad sva nebesa, sjede uz tvoju desnu, te obećanog Duha Svetoga na današnji dan izli na posinjenu djecu. – Stoga sav svijet na krugu zemaljskom kliče zanosnom radošću, a i višnje sile i s njima anđeoske vlasti zajedno pjevaju pjesmu tvoje slave govoreći bez prestanka:","kn":"Predslovlje: Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi. Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospodinu našem, koji je uzašao nad sva nebesa i sjeo s desne Tvoje i na današnji dan izlio obećanoga Duha Svetoga na Božje posinke. Zato kliče čitav svijet i svemir pun veselja. A i višnje moći i anđeoske vlasti pjevaju pjesmu Tvoje slave govoreći bez prestanka:","knRef":"Kniewald 1942, str. 344–345 (snimka 173) (OCR)"},"610b39e3cba8b6b1":{"t":"Iv 14, 26\nDuh će vas Sveti poučiti, <i>aleluja</i>,\no svemu što vam kažem, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Iv. 14, 26). Duh će vas Sveti poučiti, aleluja, u svemu, što vam kažem, aleluja, aleluja.","knRef":"Kniewald 1942, str. 346–347 (snimka 174) (OCR)"},"017374a0397275e4":{"t":"<i>Pomolimo se</i>.\nBliz budi, molimo, Gospodine, puku svomu i brani od neprijateljskog bijesa one koje si nahranio nebeskim tajnama.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bliz budi, molimo, Gospodine, puku svomu, i brani od neprijateljskoga bijesa one, koje si napunio nebeskim tajnama, ipo G. n.","knRef":"Kniewald 1942, str. 346–347 (snimka 174) (OCR)"}}});
